 return L.replace(/\/+$/,'');
}
function IJ_action(){
 var L=IJ_base();
 try{
  var h=String(java.ajax(L+'/'));
  var m=h.match(/action=['"](\/search[^'"]*\.html)['"]/);
  if(m) return L+m[1];
 }catch(e){}
 return L+'/search7e.html';
}
